[{"type":"text","text":"import debounce from "lodash.debounce"
import throttle from "lodash.throttle"
import { ref } from "vue"
import { api } from "@/env/index"
import { useUserStore } from "@/store/user"

const userStore = useUserStore()
const { setToken, setUserInfo } = userStore

// 文件类型判断
export const getFileTypeByUrl = (url) => {
  return url ? url.substring(url.lastIndexOf(".") + 1).toLocaleLowerCase() : ""
}
export function _debounce(func: Function) {
  return debounce(() => func(), 500, { leading: true, trailing: false })
}

export function _throttle(func: Function) {
  return throttle(() => func(), 500, { leading: false, trailing: true })
}

export const getUrl = (path: string) => {
  let url;
  // #ifdef MP-WEIXIN
  url = path;
  //#endif
  // #ifdef H5
  url = new URL(path, import.meta.url).pathname;
  //#endif
  return url;
};

export const goto = (url) => {
  if (!url) {
    return
  }
  uni.navigateTo({
    url,
  })
}

export async function request(params: UniApp.RequestOptions): Promise<any> {
  const form: UniApp.RequestOptions = {
    url: `${api}/v2.0/${params.url}`,
  }
  const token = ref(uni.getStorageSync('token'))
  if (token.value) {
    form.header = {
      Authorization: `Bearer ${token.value}`,
    }
  }
  if(params.method == 'file') {
    const res: AnyObject = await uni.uploadFile({
      url:  `${api}/v2.0/${params.url}`,
      header: form.header,
      files: params.files,
      formData: params.formData,
      name: params.name || 'file',
      filePath: params.filePath,
    })
    res.data = JSON.parse(res.data)
    return Promise.resolve(res.data)
  }
  form.method = params.method || 'GET'
  form.data = params.data
  console.log(params.data, 'params.data')
  console.log(`${api}/v2.0/${params.url}`, 'params.url')
  if (params.headers) {
    form.header = {...form.header, ...params.headers}
  }
  try {
    const res: AnyObject = await uni.request(form)
    const data = res.data
    console.log(res.data, 'res.data')
    if (data.code == 401) {
      setToken("")
      setUserInfo()
      uni.showToast({
        title: data.msg,
        icon: "none",
        duration: 1000,
      })
      uni.navigateTo({
        url: "/pages/login/index",
      })
      return Promise.reject(res)
    } else if (data.code <= 200) {
      return Promise.resolve(res.data)
    }else if(data.code == 10000){
      return Promise.resolve(res.data)
    } else {
      uni.showToast({
        title: data.msg || data.message,
        icon: "none",
        duration: 1000,
      })
      return Promise.reject(res.data)
    }
  } catch (err) {
    uni.showToast({
      title: "系统异常，请联系管理员",
      icon: "none",
      duration: 1000,
    })
    Promise.reject(err)
  }
}


export function filePreview(file) {
  const url = file.rawData || file.filePath
  // 处理路由加了 base 的情况
  let transferUrl
  // #ifdef H5
  transferUrl = `${window.location.pathname}${url}`.replace(/\/\//g, "/")
  // #endif
  // #ifdef MP-WEIXIN
  transferUrl = `${BASE_URL}${url}`.replace(/\/\//g, "/")
  // #endif
  const type = file.fileType || getFileTypeByUrl(url)
  const fileName = file.fileName || `File${Date.now()}.${type}`

  if (".jpeg.jpg.png".includes(type.toLowerCase())) {
    // 图片预览
    uni.previewImage({
      urls: [transferUrl],
    })
    return
  }

  // #ifdef H5
  if (".pdf".includes(type.toLowerCase())) {
    console.log("🚀 ~ filePreview ~ transferUrl:", import.meta.env.VITE_APP_API_PROXY + transferUrl)
    if (window.android) {
      console.log("in app");
      openPDF({
        title: '附件预览',
        url: import.meta.env.VITE_APP_API_PROXY + transferUrl
      });
      return
    } else {
      // pdf预览
      uni.navigateTo({
        url: `/pages/common/pdf?url=${transferUrl}`,
      })
      return
    }
  } else {
    // 其他文件下载查看
    fetch(transferUrl)
      .then((res) => res.blob())
      .then((res) => {
        const link = document.createElement("a")
        link.download = fileName
        link.href = URL.createObjectURL(res)
        link.click()
        URL.revokeObjectURL(link.href)
      })
  }
  // #endif

  // #ifdef MP-WEIXIN
  uni.downloadFile({
    url: transferUrl,
    success: function (res) {
      const filePath = res.tempFilePath
      uni.openDocument({
        filePath: filePath,
        showMenu: true,
        complete: function (res) {
          console.log("res: ", res)
        },
      })
    },
    complete: function (res) {
      console.log("res: ", res)
    },
  })
  // #endif
}

export const getDictLabel = (val, options) => {
  return options
    ?.filter((e) => String(val)?.split(',').includes(e.value))
    .map((item) => item.text)
    .join('，') || val
}
"}]

