import { defineConfig, loadEnv } from 'vite'
import uni from '@dcloudio/vite-plugin-uni'

/** 与 main 分支一致：H5 默认走同源 /api，由 dev server 或 nginx 反代到苏住房 test 网关 */
const DEFAULT_API_PROXY_TARGET =
  'http://unlimited.c.h5-zhishu.shimin.mobile.v2.suzhufang.shiqu.suzhou.test.zhi.com'

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, process.cwd(), '')
  const proxyTarget = env.VITE_API_PROXY_TARGET || DEFAULT_API_PROXY_TARGET
  const uniPlugin = (uni as unknown as { default?: typeof uni }).default?.() ?? uni()
  return {
    plugins: [uniPlugin],
    server: {
      proxy: {
        '/api': {
          target: proxyTarget,
          changeOrigin: true,
          configure(proxy) {
            proxy.on('proxyRes', (proxyRes, req) => {
              proxyRes.headers['frontend-proxy'] = `${proxyTarget}${req.url ?? ''}`
            })
          },
        },
      },
    },
  }
})

