    proxy_pass http://unlimited.c.h5-zhishu.shimin.mobile.v2.suzhufang.shiqu.suzhou.test.zhi.com/;
    proxy_http_version 1.1;
    proxy_set_header Host unlimited.c.h5-zhishu.shimin.mobile.v2.suzhufang.shiqu.suzhou.test.zhi.com;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
}

